// brandPlot: Observable Plot (ISC, observablehq.com/plot) in your brand.
// Generated by product-aesthetics; regenerate with
//   pa add observable-plot --brand <your brand file>
//
// brandPlot(options) is Plot.plot(options) with your brand as the defaults:
//   type     your sans font, in your text colour, on a transparent background
//   colour   categories take brandColors.categorical (led by your primary);
//            numbers take brandColors.sequential (a tint of primary to a deep shade),
//            and ordered categories take evenly spaced steps along it
//   grid     Plot's default grid (text colour at 10%) becomes your border colour
//   tips     tooltips fill with your background colour
// Anything you pass wins: your own style, color.range, color.scheme or
// color.interpolate, and any grid colour you set.
import * as Plot from '@observablehq/plot';

/* brand:start */
export const brandColors = {
  name: 'Stock',
  font: 'system-ui, sans-serif',
  background: '#ffffff', foreground: '#000000', primary: '#4269d0', accent: '#4269d0',
  muted: '#f4f4f5', mutedForeground: '#71717a', border: '#e4e4e7',
  categorical: ['#4269d0', '#efb118', '#ff725c', '#6cc5b0', '#3ca951', '#ff8ab7', '#a463f2', '#97bbf5'],
  sequential: ['#f7fbff', '#08306b'],
  dark: {
    background: '#18181b', foreground: '#ffffff', primary: '#4269d0', accent: '#4269d0',
    muted: '#27272a', mutedForeground: '#a1a1aa', border: '#3f3f46',
    categorical: ['#4269d0', '#efb118', '#ff725c', '#6cc5b0', '#3ca951', '#ff8ab7', '#a463f2', '#97bbf5'],
    sequential: ['#08306b', '#f7fbff'],
  },
};
/* brand:end */

/** A colour function for t in [0, 1] that runs through the given stops. */
export function brandRamp(stops) {
  const rgb = stops.map((h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)));
  const n = rgb.length - 1;
  return (t) => {
    const x = Math.min(1, Math.max(0, Number(t) || 0)) * n;
    const i = Math.min(n - 1, Math.floor(x));
    const f = x - i;
    return `rgb(${rgb[i].map((v, k) => Math.round(v + (rgb[i + 1][k] - v) * f)).join(', ')})`;
  };
}

const LEAVE = new Set(['identity', 'diverging', 'diverging-log', 'diverging-pow', 'diverging-sqrt', 'diverging-symlog']);

const kebab = (k) => (k.startsWith('--') ? k : k.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`));
const cssText = (style) =>
  style == null
    ? ''
    : typeof style === 'string'
      ? style
      : Object.entries(style)
          .filter(([, v]) => v != null && v !== '')
          .map(([k, v]) => `${kebab(k)}: ${v}`)
          .join('; ');
const join = (...parts) => parts.filter(Boolean).join('; ');

/**
 * Plot.plot with your brand as the defaults. `theme: 'dark'` uses your dark
 * scheme. Returns what Plot.plot returns: an SVG, or a figure when there's a
 * title, caption or legend.
 */
export function brandPlot(options = {}, { theme = 'light' } = {}) {
  const c = theme === 'dark' ? brandColors.dark : brandColors;
  const color = options.color != null && typeof options.color === 'object' ? options.color : {};
  const base = {
    ...options,
    // A style string, so --plot-background reaches Plot's tooltips; yours comes last and wins.
    style: join(
      cssText({ fontFamily: brandColors.font, color: c.foreground, background: 'transparent', '--plot-background': c.background }),
      cssText(options.style),
    ),
    color: { ...color, style: join(cssText({ fontFamily: brandColors.font, color: c.foreground }), cssText(color.style)) },
  };

  let chart = Plot.plot(base);

  // Colour the colour scale, unless you chose its colours yourself. Plot only
  // knows whether it's categories or numbers once it has seen the data, so
  // read the scale off this render and draw again with brand colours.
  const chose = color.range !== undefined || color.scheme !== undefined || color.interpolate !== undefined;
  const scale = chose ? undefined : chart.scale('color');
  if (scale && !LEAVE.has(scale.type)) {
    const ramp = brandRamp(c.sequential);
    const n = scale.domain?.length ?? 0;
    // Like Plot: categories unless you asked for type 'ordinal' (ordered
    // categories), which get steps along the ramp, skipping the palest tint.
    const discrete = scale.type === 'ordinal' || scale.type === 'categorical';
    const brand = !discrete
      ? { interpolate: ramp }
      : color.type === 'ordinal'
        ? { range: Array.from({ length: n }, (_, i) => ramp(n < 2 ? 0.55 : 0.2 + (0.8 * i) / (n - 1))) }
        : { range: c.categorical };
    chart = Plot.plot({ ...base, color: { ...base.color, ...brand } });
  }

  // Plot draws grids in the text colour at 10% opacity. Swap that default (and
  // only that default) for the brand's border colour at full strength.
  for (const g of chart.querySelectorAll('g[aria-label$="-grid"]')) {
    if (g.getAttribute('stroke') === 'currentColor' && g.getAttribute('stroke-opacity') === '0.1') {
      g.setAttribute('stroke', c.border);
      g.removeAttribute('stroke-opacity');
    }
  }

  // A figure (title, caption, legend) takes the same type as the chart.
  if (chart.tagName?.toLowerCase() === 'figure') {
    const svg = [...chart.children].filter((e) => e.tagName.toLowerCase() === 'svg').pop(); // legends come first
    chart.style.fontFamily ||= svg?.style.fontFamily ?? brandColors.font;
    chart.style.color ||= svg?.style.color ?? c.foreground;
  }
  return chart;
}
